using StackExchange.Redis;namespace SyWater.Places.Api.Security;public interface ITokenRevocationChecker{    Task<bool> IsRevokedAsync(string? tokenId, string? userId, long? issuedAtEpochSeconds);}public sealed class RedisTokenRevocationChecker(IConnectionMultiplexer redis) : ITokenRevocationChecker{    public const string JtiPrefix = "iam:revoked:jti:";    public const string UserPrefix = "iam:revoked-before:";    public async Task<bool> IsRevokedAsync(string? tokenId, string? userId, long? issuedAtEpochSeconds)    {        var db = redis.GetDatabase();        if (!string.IsNullOrEmpty(tokenId) && await db.KeyExistsAsync(JtiPrefix + tokenId))            return true;        if (string.IsNullOrEmpty(userId) || issuedAtEpochSeconds is null)            return false;        var revokedBefore = await db.StringGetAsync(UserPrefix + userId);        return revokedBefore.HasValue               && long.TryParse(revokedBefore.ToString(), out var before)               && issuedAtEpochSeconds.Value <= before;    }}